USE campusconnect;

-- CREATE: register a student (password_hash must be generated by the application)
INSERT INTO users (full_name, email, password_hash, department, study_year, role)
VALUES ('Demo Student', 'student@example.edu', '<application-generated-hash>', 'CSE', 2, 'student');

-- READ: list the next campus events with registration counts
SELECT * FROM upcoming_events_view ORDER BY event_date LIMIT 20;

-- READ: show clubs and active membership counts
SELECT c.club_id, c.name, c.category, COUNT(cm.user_id) AS active_members
FROM clubs c LEFT JOIN club_memberships cm
  ON c.club_id = cm.club_id AND cm.status = 'active'
GROUP BY c.club_id, c.name, c.category ORDER BY c.name;

-- UPDATE: edit an event's location and capacity
UPDATE events SET location = 'Central Seminar Hall', capacity = 150
WHERE event_id = 1;

-- UPDATE: cancel a student's registration without deleting the history
UPDATE event_registrations SET status = 'cancelled'
WHERE event_id = 1 AND user_id = 2;

-- DELETE: admin-only removal of an event; related registrations cascade
DELETE FROM events WHERE event_id = 1;

-- DELETE: remove expired announcements as a scheduled maintenance task
DELETE FROM announcements WHERE expires_at IS NOT NULL AND expires_at < CURRENT_TIMESTAMP;
